#!/usr/bin/env python3
"""Mirror a single page: download HTML + css/js/img/fonts, rewrite URLs to local relative paths."""
import os, re, sys, hashlib, urllib.request, urllib.parse

SRC, OUT = sys.argv[1], sys.argv[2]
UA = {"User-Agent": "Mozilla/5.0 (Macintosh) AppleWebKit/537.36 Chrome/120 Safari/537.36"}
done = {}

def get(url):
    req = urllib.request.Request(url, headers=UA)
    with urllib.request.urlopen(req, timeout=40) as r:
        return r.read()

def local_path(url, kind):
    p = urllib.parse.urlparse(url)
    name = os.path.basename(p.path) or "file"
    h = hashlib.md5(url.encode()).hexdigest()[:6]
    base, ext = os.path.splitext(name)
    return f"{kind}/{base[:60]}-{h}{ext}"

def fetch(url, kind):
    if url in done:
        return done[url]
    rel = local_path(url, kind)
    try:
        data = get(url)
    except Exception as e:
        print("FAIL", url, e)
        done[url] = None
        return None
    done[url] = rel
    full = os.path.join(OUT, rel)
    os.makedirs(os.path.dirname(full), exist_ok=True)
    if kind == "css":
        txt = data.decode("utf-8", "ignore")
        data = rewrite_css(txt, url).encode()
    open(full, "wb").write(data)
    return rel

def rewrite_css(txt, base):
    def rep(m):
        u = m.group(2).strip()
        if u.startswith("data:") or u.startswith("#"):
            return m.group(0)
        full = urllib.parse.urljoin(base, u)
        ext = os.path.splitext(urllib.parse.urlparse(full).path)[1].lower()
        kind = "fonts" if ext in (".woff", ".woff2", ".ttf", ".otf", ".eot") else "img"
        rel = fetch(full, kind)
        if not rel:
            return m.group(0)
        return f"url({m.group(1)}../{rel}{m.group(1)})"
    return re.sub(r"url\((['\"]?)([^)'\"]+)\1\)", rep, txt)

html = get(SRC).decode("utf-8", "ignore")
EXT_IMG = r"\.(?:png|jpe?g|webp|svg|gif|ico|avif)"

def sub_attr(m):
    attr, q, u = m.group(1), m.group(2), m.group(3)
    full = urllib.parse.urljoin(SRC, u)
    host = urllib.parse.urlparse(full).netloc
    path = urllib.parse.urlparse(full).path.lower()
    if path.endswith(".css") or "stylesheet" in m.group(0):
        rel = fetch(full, "css")
    elif path.endswith(".js"):
        rel = fetch(full, "js")
    elif re.search(EXT_IMG + "$", path) or path.endswith((".woff2", ".woff", ".mp4")):
        rel = fetch(full, "img")
    else:
        return m.group(0)
    return f'{attr}={q}{rel}{q}' if rel else m.group(0)

# stylesheet links
def link_css(m):
    tag = m.group(0)
    h = re.search(r'href=(["\'])([^"\']+)\1', tag)
    if not h or "stylesheet" not in tag:
        return tag
    full = urllib.parse.urljoin(SRC, h.group(2))
    rel = fetch(full, "css")
    return tag.replace(h.group(0), f'href="{rel}"') if rel else tag
html = re.sub(r"<link\b[^>]*>", link_css, html)

# scripts
def script_tag(m):
    tag = m.group(0)
    s = re.search(r'src=(["\'])([^"\']+)\1', tag)
    if not s:
        return tag
    full = urllib.parse.urljoin(SRC, s.group(2))
    if "detailersmovement.com" not in full:
        return tag
    rel = fetch(full, "js")
    return tag.replace(s.group(0), f'src="{rel}"') if rel else tag
html = re.sub(r"<script\b[^>]*>", script_tag, html)

# images in any attribute (src, data-src, srcset-less, href icons, poster, etc.)
def img_attr(m):
    full = urllib.parse.urljoin(SRC, m.group(2))
    if "detailersmovement.com" not in full:
        return m.group(0)
    rel = fetch(full, "img")
    return f'{m.group(1)}"{rel}"' if rel else m.group(0)
html = re.sub(r'((?:src|data-src|href|data-lazy-src|poster)=)["\']([^"\']+' + EXT_IMG + r'(?:\?[^"\']*)?)["\']', img_attr, html)

# srcset
def srcset(m):
    parts = []
    for item in m.group(2).split(","):
        bits = item.strip().split()
        if not bits:
            continue
        full = urllib.parse.urljoin(SRC, bits[0])
        rel = fetch(full, "img") if "detailersmovement.com" in full else None
        parts.append(" ".join([rel or bits[0]] + bits[1:]))
    return f'{m.group(1)}"{", ".join(parts)}"'
html = re.sub(r'((?:srcset|data-srcset)=)["\']([^"\']+)["\']', srcset, html)

# inline style url(...) and <style> blocks
html = re.sub(r"url\((['\"]?)([^)'\"]+)\1\)",
              lambda m: (lambda r: f"url({m.group(1)}{r}{m.group(1)})" if r else m.group(0))(
                  fetch(urllib.parse.urljoin(SRC, m.group(2)), "img")
                  if not m.group(2).startswith(("data:", "#")) and "detailersmovement.com" in urllib.parse.urljoin(SRC, m.group(2)) else None),
              html)

# fix preload/prefetch & absolute site links -> stay on original for pages
os.makedirs(OUT, exist_ok=True)
open(os.path.join(OUT, "index.html"), "w", encoding="utf-8").write(html)
print("ok", len([v for v in done.values() if v]), "files,", len([v for v in done.values() if not v]), "failed")

